class Solution:
    def getSumAbsoluteDifferences(self, nums: List[int]) -> List[int]:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + nums[i]
        res = []
        for i in range(n):
            left = i * nums[i] - prefix[i]
            right = (prefix[n] - prefix[i+1]) - (n - i - 1) * nums[i]
            res.append(left + right)
        return res

class Solution:
    def boxDelivering(self, boxes: List[List[int]], portsCount: int, maxBoxes: int, maxWeight: int) -> int:
        n = len(boxes)
        # diff[i] = 1 if boxes[i] and boxes[i-1] go to different ports
        diff = [0] * n
        for i in range(1, n):
            if boxes[i][0] != boxes[i-1][0]:
                diff[i] = 1
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i+1] = pre[i] + diff[i]
        dp = [0] * (n + 1)
        j = 0
        weight = 0
        for i in range(1, n + 1):
            weight += boxes[i-1][1]
            while i - j > maxBoxes or weight > maxWeight:
                weight -= boxes[j][1]
                j += 1
            # trips = pre[i] - pre[j] + 2 (go and come back)
            dp[i] = dp[j] + (pre[i] - pre[j]) + 2
            # try to optimize: find better j
            for k in range(j, i):
                val = dp[k] + (pre[i] - pre[k]) + 2
                if val < dp[i]:
                    dp[i] = val
                if val == dp[i]:
                    break
        return dp[n]

