class Solution:
    def stoneGameVII(self, stones: List[int]) -> int:
        n = len(stones)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + stones[i]
        def rangeSum(i, j):
            return prefix[j+1] - prefix[i]
        dp = [[0]*n for _ in range(n)]
        for length in range(2, n+1):
            for i in range(n - length + 1):
                j = i + length - 1
                # remove left: score = rangeSum(i+1,j), then opponent plays dp[i+1][j]
                # remove right: score = rangeSum(i,j-1), then opponent plays dp[i][j-1]
                dp[i][j] = max(rangeSum(i+1, j) - dp[i+1][j], rangeSum(i, j-1) - dp[i][j-1])
        return dp[0][n-1]

class Solution:
    def maxHeight(self, cuboids: List[List[int]]) -> int:
        for c in cuboids:
            c.sort()
        cuboids.sort()
        n = len(cuboids)
        dp = [c[2] for c in cuboids]
        for i in range(1, n):
            for j in range(i):
                if cuboids[j][0] <= cuboids[i][0] and cuboids[j][1] <= cuboids[i][1] and cuboids[j][2] <= cuboids[i][2]:
