class Solution:
    def reformatNumber(self, number: str) -> str:
        digits = number.replace(' ', '').replace('-', '')
        res = []
        i = 0
        n = len(digits)
        while n - i > 4:
            res.append(digits[i:i+3])
            i += 3
        if n - i == 4:
            res.append(digits[i:i+2])
