class Solution:
    def maximumBinaryString(self, binary: str) -> str:
        n = len(binary)
        # find first 0
        first_zero = binary.find('0')
        if first_zero == -1:
            return binary
        # count zeros from first_zero onwards
        zeros = binary[first_zero:].count('0')
        # result: all 1s except position (first_zero + zeros - 1) is 0
        res = ['1'] * n
        res[first_zero + zeros - 1] = '0'
        return ''.join(res)

class Solution:
    def eatenApples(self, apples: List[int], days: List[int]) -> int:
        import heapq
        n = len(apples)
        heap = []
        eaten = 0
        day = 0
        while day < n or heap:
            if day < n and apples[day] > 0:
                heapq.heappush(heap, (day + days[day], apples[day]))
            while heap and heap[0][0] <= day:
                heapq.heappop(heap)
            if heap:
                exp, cnt = heapq.heappop(heap)
                eaten += 1
                if cnt > 1:
                    heapq.heappush(heap, (exp, cnt - 1))
            day += 1
        return eaten

