class Solution:
    def maximizeXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        nums.sort()
        q_sorted = sorted(enumerate(queries), key=lambda x: x[1][1])
        trie = {}
        res = [-1] * len(queries)
        idx = 0
        for qi, (xi, mi) in q_sorted:
            while idx < len(nums) and nums[idx] <= mi:
                node = trie
                for bit in range(30, -1, -1):
                    b = (nums[idx] >> bit) & 1
                    if b not in node:
                        node[b] = {}
                    node = node[b]
                idx += 1
            if not trie:
                res[qi] = -1
                continue
            node = trie
            xor_val = 0
            for bit in range(30, -1, -1):
                want = (xi >> bit) & 1 ^ 1
                if want in node:
                    xor_val |= (1 << bit)
                    node = node[want]
                else:
                    node = node[1 - want]
            res[qi] = xor_val
        return res

