class Solution:
    def waysToSplit(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + nums[i]
        total = prefix[n]
        res = 0
        for i in range(1, n - 1):
            left_sum = prefix[i]
            if left_sum * 3 > total:
                break
            # find min j: prefix[j] - prefix[i] >= prefix[i]
            lo, hi = i + 1, n - 1
            while lo < hi:
                mid = (lo + hi) // 2
                if prefix[mid] - prefix[i] >= left_sum:
                    hi = mid
                else:
                    lo = mid + 1
            j_min = lo
            # find max j: prefix[j] - prefix[i] <= total - prefix[j] => 2*prefix[j] <= total + prefix[i]
            lo, hi = j_min, n - 1
            while lo < hi:
                mid = (lo + hi + 1) // 2
                if 2 * prefix[mid] <= total + prefix[i]:
                    lo = mid
                else:
                    hi = mid - 1
            j_max = lo
            if j_min <= j_max:
                res = (res + j_max - j_min + 1) % MOD
        return res

class Solution:
    def minOperations(self, target: List[int], arr: List[int]) -> int:
        import bisect
        pos = {v: i for i, v in enumerate(target)}
        # map arr to indices in target
        mapped = [pos[x] for x in arr if x in pos]
        # LIS on mapped
        tails = []
        for x in mapped:
            idx = bisect.bisect_left(tails, x)
            if idx == len(tails):
                tails.append(x)
            else:
                tails[idx] = x
        return len(target) - len(tails)

class Solution:
    def solve(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        MOD = 10**9 + 7
        n = len(nums)
        import math
        B = int(math.sqrt(n)) + 1
        # precompute suffix sums for small steps
        cache = {}
        for y in range(1, B):
            suf = [0] * (n + 1)
            for i in range(n - 1, -1, -1):
                suf[i] = (nums[i] + (suf[i + y] if i + y <= n else 0)) % MOD
            cache[y] = suf
        res = []
        for x, y in queries:
            if y < B:
                res.append(cache[y][x])
            else:
                s = 0
                i = x
                while i < n:
                    s = (s + nums[i]) % MOD
                    i += y
                res.append(s)
        return res

class Solution:
    def maximumGain(self, s: str, x: int, y: int) -> int:
        def remove(s, first, second, score):
            stack = []
            total = 0
            for c in s:
                if stack and stack[-1] == first and c == second:
                    stack.pop()
                    total += score
                else:
                    stack.append(c)
            return total, ''.join(stack)
        if x >= y:
            score1, remaining = remove(s, 'a', 'b', x)
            score2, _ = remove(remaining, 'b', 'a', y)
        else:
            score1, remaining = remove(s, 'b', 'a', y)
            score2, _ = remove(remaining, 'a', 'b', x)
        return score1 + score2

class Solution:
    def constructDistancedSequence(self, n: int) -> List[int]:
        size = 2 * n - 1
        res = [0] * size
        used = [False] * (n + 1)
        def dfs(idx):
            if idx == size:
                return True
            if res[idx] != 0:
                return dfs(idx + 1)
            for num in range(n, 0, -1):
                if used[num]:
                    continue
                if num == 1:
                    res[idx] = 1
                    used[1] = True
                    if dfs(idx + 1):
                        return True
                    res[idx] = 0
                    used[1] = False
                else:
                    if idx + num < size and res[idx + num] == 0:
                        res[idx] = res[idx + num] = num
                        used[num] = True
                        if dfs(idx + 1):
                            return True
                        res[idx] = res[idx + num] = 0
                        used[num] = False
            return False
        dfs(0)
        return res

class Solution:
    def checkWays(self, pairs: List[List[int]]) -> int:
        from collections import defaultdict
        adj = defaultdict(set)
        for u, v in pairs:
            adj[u].add(v)
            adj[v].add(u)
        nodes = list(adj.keys())
        n = len(nodes)
        # root must be connected to all other nodes
        root = None
        for node in nodes:
            if len(adj[node]) == n - 1:
                root = node
                break
        if root is None:
            return 0
        res = 1
        for node in nodes:
            if node == root:
                continue
            # find parent: node with smallest degree among adj[node] that has degree >= degree of node
            parent = None
            min_deg = float('inf')
            for neighbor in adj[node]:
                if len(adj[neighbor]) >= len(adj[node]) and len(adj[neighbor]) < min_deg:
                    min_deg = len(adj[neighbor])
                    parent = neighbor
            if parent is None:
                return 0
            # adj[node] - {parent} must be subset of adj[parent]
            for neighbor in adj[node]:
                if neighbor != parent and neighbor not in adj[parent]:
                    return 0
            if len(adj[node]) == len(adj[parent]):
                res = 2
        return res

