class Solution:
    def minimumHammingDistance(self, source: List[int], target: List[int], allowedSwaps: List[List[int]]) -> int:
        from collections import defaultdict, Counter
        n = len(source)
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py
        for a, b in allowedSwaps:
            union(a, b)
        groups = defaultdict(list)
        for i in range(n):
            groups[find(i)].append(i)
        res = 0
        for indices in groups.values():
            src_cnt = Counter(source[i] for i in indices)
            tgt_cnt = Counter(target[i] for i in indices)
            # matched pairs
            matched = sum((src_cnt & tgt_cnt).values())
            res += len(indices) - matched
        return res

class Solution:
    def minimumTimeRequired(self, jobs: List[int], k: int) -> int:
        jobs.sort(reverse=True)
        n = len(jobs)
        workers = [0] * k
        self.ans = sum(jobs)
        def dfs(idx):
            if idx == n:
                self.ans = min(self.ans, max(workers))
                return
            seen = set()
            for i in range(k):
                if workers[i] in seen:
                    continue
                if workers[i] + jobs[idx] >= self.ans:
                    continue
                seen.add(workers[i])
                workers[i] += jobs[idx]
                dfs(idx + 1)
                workers[i] -= jobs[idx]
        dfs(0)
        return self.ans

