class Solution:
    def canMouseWin(self, grid: List[str], catJump: int, mouseJump: int) -> bool:
        m, n = len(grid), len(grid[0])
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 'C': cat_start = (i, j)
                elif grid[i][j] == 'M': mouse_start = (i, j)
                elif grid[i][j] == 'F': food = (i, j)
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(mouse, cat, turns):
            if turns >= 128:
                return False
            if mouse == cat:
                return False
            if cat == food:
                return False
            if mouse == food:
                return True
            if turns % 2 == 0:  # mouse's turn
                mx, my = mouse
                for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    for jump in range(mouseJump + 1):
                        nx, ny = mx + dx*jump, my + dy*jump
                        if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != '#':
                            if dp((nx, ny), cat, turns + 1):
                                return True
                        else:
                            break
                # stay
                if dp(mouse, cat, turns + 1):
                    return True
                return False
            else:  # cat's turn
                cx, cy = cat
                for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    for jump in range(catJump + 1):
                        nx, ny = cx + dx*jump, cy + dy*jump
                        if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != '#':
                            if not dp(mouse, (nx, ny), turns + 1):
                                return False
                        else:
                            break
                if not dp(mouse, cat, turns + 1):
                    return False
                return True
        return dp(mouse_start, cat_start, 0)

class Solution:
    def getFood(self, grid: List[List[str]]) -> int:
        from collections import deque
        m, n = len(grid), len(grid[0])
        q = deque()
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '*':
                    q.append((i, j, 0))
                    grid[i][j] = 'V'
                    break
            else:
                continue
            break
        while q:
            x, y, d = q.popleft()
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != 'X' and grid[nx][ny] != 'V':
                    if grid[nx][ny] == '#':
                        return d + 1
                    grid[nx][ny] = 'V'
                    q.append((nx, ny, d+1))
        return -1

