class Solution:
    def minimumTeachings(self, n: int, languages: List[List[int]], friendships: List[List[int]]) -> int:
        lang_sets = [set(l) for l in languages]
        # find pairs that cannot communicate
        cannot = set()
        for u, v in friendships:
            u -= 1; v -= 1
            if not lang_sets[u] & lang_sets[v]:
                cannot.add((u, v))
        if not cannot:
            return 0
        # people involved
        people = set()
        for u, v in cannot:
            people.add(u)
            people.add(v)
        # try each language
        min_teach = len(people)
        for lang in range(1, n + 1):
            teach = sum(1 for p in people if lang not in lang_sets[p])
            min_teach = min(min_teach, teach)
        return min_teach

class Solution:
    def decode(self, encoded: List[int]) -> List[int]:
        n = len(encoded) + 1
        # total xor of 1..n
        total_xor = 0
        for i in range(1, n + 1):
            total_xor ^= i
        # xor of arr[1]^arr[2]^...^arr[n-1] = encoded[1]^encoded[3]^...
        rest_xor = 0
        for i in range(1, len(encoded), 2):
            rest_xor ^= encoded[i]
        arr = [total_xor ^ rest_xor]
        for e in encoded:
            arr.append(arr[-1] ^ e)
        return arr

class Solution:
    def waysToFillArray(self, queries: List[List[int]]) -> List[int]:
        MOD = 10**9 + 7
        MAX = 10030
        fact = [1] * MAX
        for i in range(1, MAX):
            fact[i] = fact[i-1] * i % MOD
        inv_fact = [1] * MAX
        inv_fact[MAX-1] = pow(fact[MAX-1], MOD-2, MOD)
        for i in range(MAX-2, -1, -1):
            inv_fact[i] = inv_fact[i+1] * (i+1) % MOD
        def comb(n, r):
            if r < 0 or r > n: return 0
            return fact[n] * inv_fact[r] % MOD * inv_fact[n-r] % MOD
        res = []
        for n, k in queries:
            ans = 1
            val = k
            d = 2
            while d * d <= val:
                if val % d == 0:
                    e = 0
                    while val % d == 0:
                        e += 1
                        val //= d
                    ans = ans * comb(n + e - 1, e) % MOD
                d += 1
            if val > 1:
                ans = ans * comb(n, 1) % MOD
            res.append(ans)
        return res

class Solution:
    def maximumTime(self, time: str) -> str:
        t = list(time)
        if t[0] == '?':
            t[0] = '2' if t[1] in '?0123' else '1'
        if t[1] == '?':
            t[1] = '3' if t[0] == '2' else '9'
        if t[3] == '?':
            t[3] = '5'
        if t[4] == '?':
            t[4] = '9'
        return ''.join(t)

class Solution:
    def kthLargestValue(self, matrix: List[List[int]], k: int) -> int:
        m, n = len(matrix), len(matrix[0])
        dp = [[0]*(n+1) for _ in range(m+1)]
        vals = []
        for i in range(1, m+1):
            for j in range(1, n+1):
                dp[i][j] = matrix[i-1][j-1] ^ dp[i-1][j] ^ dp[i][j-1] ^ dp[i-1][j-1]
                vals.append(dp[i][j])
        vals.sort(reverse=True)
        return vals[k-1]

class Solution:
    def findDistance(self, root: Optional[TreeNode], p: int, q: int) -> int:
        def lca(node, p, q):
            if not node or node.val == p or node.val == q:
                return node
            left = lca(node.left, p, q)
            right = lca(node.right, p, q)
            if left and right:
                return node
            return left or right
        def depth(node, target, d):
            if not node:
                return -1
            if node.val == target:
                return d
            left = depth(node.left, target, d+1)
            if left != -1:
                return left
            return depth(node.right, target, d+1)
        ancestor = lca(root, p, q)
        return depth(ancestor, p, 0) + depth(ancestor, q, 0)
